import{_ as a,o as i,c as t,a5 as s}from"./chunks/framework.a5no_H3L.js";const p=JSON.parse('{"title":"Ghidra 静态分析与脚本化","description":"上一篇用 IDA Pro 完成了静态分析，这一篇用免费的 Ghidra 做同样的事。Ghidra 是 NSA 开源发布的逆向框架，自带反编译器、支持脚本化，是入门和中小规模分析的高性价比选择。","frontmatter":{"type":"howto","level":"basic"},"headers":[],"relativePath":"reverse-engineering/05-static-analysis/chapter-05-ghidra.md","filePath":"reverse-engineering/05-static-analysis/chapter-05-ghidra.md"}'),r={name:"reverse-engineering/05-static-analysis/chapter-05-ghidra.md"};function n(d,e,l,c,h,g){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="ghidra-静态分析与脚本化" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">Ghidra 静态分析与脚本化 <a class="header-anchor" href="#ghidra-静态分析与脚本化" aria-label="Permalink to &quot;Ghidra 静态分析与脚本化&quot;">​</a></h1><blockquote data-src-line="4" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><p data-src-line="4" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">上一篇用 IDA Pro 完成了静态分析，这一篇用免费的 Ghidra 做同样的事。Ghidra 是 NSA 开源发布的逆向框架，自带反编译器、支持脚本化，是入门和中小规模分析的高性价比选择。</p></blockquote><p data-src-line="6" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>前置条件</strong>：已读 <a href="./chapter-04-ida-pro.html">IDA Pro</a>，理解函数、交叉引用、反编译这些概念；电脑上装好了 Ghidra（本文以 11.x～12.x 为准，界面跨版本稳定）和它所要求的 Java 运行环境（Ghidra 11.x 起需要 JDK 17 或更高，具体以官方安装说明为准）。同样拿一个你自己写的小程序练手。</p><h2 id="_1-安装与启动" tabindex="-1" data-src-line="8" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">1. 安装与启动 <a class="header-anchor" href="#_1-安装与启动" aria-label="Permalink to &quot;1. 安装与启动&quot;">​</a></h2><p data-src-line="10" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">Ghidra 是免安装的：从 <a href="https://ghidra-sre.org/" target="_blank" rel="noreferrer">ghidra-sre.org</a> 下载压缩包，解压后进入目录，双击 <code>ghidraRun.bat</code> 启动。首次启动会要求选择 JDK 路径——如果提示找不到 Java，说明 JDK 未安装或版本过低，装好 JDK 再启动即可。</p><p data-src-line="12" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">启动后先看到项目管理窗口。Ghidra 用「项目（Project）」来组织分析对象：新建一个项目（<code>File → New Project</code>，选 Non-Shared），然后导入你的 <code>.exe</code>（<code>File → Import File</code>）。导入对话框会识别出文件格式和架构，确认无误后，双击文件进入 <strong>CodeBrowser</strong>——这才是真正干活的主界面。</p><h2 id="_2-认识-codebrowser" tabindex="-1" data-src-line="14" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">2. 认识 CodeBrowser <a class="header-anchor" href="#_2-认识-codebrowser" aria-label="Permalink to &quot;2. 认识 CodeBrowser&quot;">​</a></h2><p data-src-line="16" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">CodeBrowser 默认有几个核心区域：</p><table tabindex="0"><thead data-src-line="18" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><tr data-src-line="18" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><th style="text-align:left;">区域</th><th style="text-align:left;">作用</th></tr></thead><tbody data-src-line="20" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><tr data-src-line="20" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;"><strong>Listing</strong>（中部）</td><td style="text-align:left;">反汇编视图，相当于 IDA 的 IDA View</td></tr><tr data-src-line="21" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;"><strong>Decompiler</strong>（右侧）</td><td style="text-align:left;">反编译伪代码窗口，Ghidra 免费自带</td></tr><tr data-src-line="22" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;"><strong>Symbol Tree</strong>（左侧）</td><td style="text-align:left;">函数、导入、导出的树状列表</td></tr><tr data-src-line="23" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;"><strong>Defined Strings</strong>（窗口）</td><td style="text-align:left;">字符串列表（<code>Window → Defined Strings</code> 打开）</td></tr></tbody></table><p data-src-line="25" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">Ghidra 的窗口都可以拖拽重排，入门保持默认即可。反编译窗口<strong>默认会自动跟随 Listing</strong>——你在反汇编里点到哪个函数，右侧就反编译哪个函数，这对快速理解逻辑非常方便。</p><h2 id="_3-分析-让-ghidra-先做一轮自动识别" tabindex="-1" data-src-line="27" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">3. 分析：让 Ghidra 先做一轮自动识别 <a class="header-anchor" href="#_3-分析-让-ghidra-先做一轮自动识别" aria-label="Permalink to &quot;3. 分析：让 Ghidra 先做一轮自动识别&quot;">​</a></h2><p data-src-line="29" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">导入文件后，Ghidra 会询问是否运行 <strong>Auto Analyze</strong>（自动分析）。选「Yes」并保持默认选项，它会自动识别函数、分析导入导出、找交叉引用。这一步对应 IDA 加载后的自动分析，<strong>不要跳过</strong>，否则后面连函数都识别不全。</p><p data-src-line="31" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">分析完成后，<code>Symbol Tree</code> 的 Functions 目录下会列出识别出的函数。如果没有符号，函数名也是 <code>FUN_140001000</code> 这种形式，和 IDA 的 <code>sub_140001000</code> 对应。</p><h2 id="_4-定位-main、反编译、查引用" tabindex="-1" data-src-line="33" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">4. 定位 main、反编译、查引用 <a class="header-anchor" href="#_4-定位-main、反编译、查引用" aria-label="Permalink to &quot;4. 定位 main、反编译、查引用&quot;">​</a></h2><p data-src-line="35" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">流程和 <a href="./chapter-04-ida-pro.html">IDA Pro</a> 完全平行，只是快捷键不同：</p><ol data-src-line="37" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><li data-src-line="37" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>定位 <code>main</code></strong>：在 Symbol Tree 的 Functions 里找 <code>main</code>；无符号时，从入口点（<code>entry</code>）追查传入 argc/argv 的调用。</li><li data-src-line="38" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>反编译</strong>：点进函数，右侧 Decompiler 自动显示伪代码；也可在 Listing 里把光标停在函数上后，用 <code>Window → Decompiler</code> 打开。</li><li data-src-line="39" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>查交叉引用</strong>：对函数、字符串、数据，把光标放上去按 <strong><code>X</code></strong>，弹出引用列表；双击跳转。</li><li data-src-line="40" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>重命名</strong>：把光标放在要改名的函数或变量上，按 <strong><code>L</code></strong>（Label），输入有意义的名字。Ghidra 里变量重命名在反编译窗口直接右键变量名修改。</li></ol><p data-src-line="42" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">和 IDA 一样，<strong>「搞懂一个就重命名一个」是 Ghidra 的核心工作习惯</strong>。重命名后，交叉引用、反编译结果都会同步更新，让整个分析越来越清晰。</p><h2 id="_5-一个示例-与-ida-篇对照" tabindex="-1" data-src-line="44" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">5. 一个示例：与 IDA 篇对照 <a class="header-anchor" href="#_5-一个示例-与-ida-篇对照" aria-label="Permalink to &quot;5. 一个示例：与 IDA 篇对照&quot;">​</a></h2><p data-src-line="46" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">继续用 <a href="./chapter-04-ida-pro.html">IDA Pro 篇</a>那个密码校验程序。在 Ghidra 里的分析路径：</p><ol data-src-line="48" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><li data-src-line="48" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><code>Window → Defined Strings</code> 打开字符串列表，找到 <code>&quot;Wrong password&quot;</code>。</li><li data-src-line="49" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">双击它跳到数据位置，光标放上去按 <code>X</code>，看到唯一引用，跳转到引用处。</li><li data-src-line="50" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">该处就是校验逻辑，右侧 Decompiler 已经给出伪代码：</li></ol><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strcmp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;secret123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    puts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Correct!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    puts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wrong password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="4" data-src-line="60" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><li data-src-line="60" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">在 Listing 里核对 <code>CALL strcmp</code> 后的 <code>CMP EAX,0x0</code> 和 <code>JNZ</code> 分支，确认无误。</li></ol><p data-src-line="62" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">和 IDA 篇对比可以发现，<strong>两者的分析概念一一对应，只是命名和快捷键不同</strong>。下表是把两篇的对应关系汇总：</p><table tabindex="0"><thead data-src-line="64" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><tr data-src-line="64" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><th style="text-align:left;">能力</th><th style="text-align:left;">IDA</th><th style="text-align:left;">Ghidra</th></tr></thead><tbody data-src-line="66" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><tr data-src-line="66" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;">反汇编视图</td><td style="text-align:left;">IDA View</td><td style="text-align:left;">Listing</td></tr><tr data-src-line="67" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;">反编译</td><td style="text-align:left;"><code>F5</code>（Hex-Rays）</td><td style="text-align:left;">Decompiler 窗口（自带）</td></tr><tr data-src-line="68" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;">跳转到地址</td><td style="text-align:left;"><code>G</code></td><td style="text-align:left;"><code>G</code></td></tr><tr data-src-line="69" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;">交叉引用</td><td style="text-align:left;"><code>X</code></td><td style="text-align:left;"><code>X</code></td></tr><tr data-src-line="70" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;">重命名</td><td style="text-align:left;"><code>N</code></td><td style="text-align:left;"><code>L</code></td></tr><tr data-src-line="71" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;">创建函数</td><td style="text-align:left;"><code>P</code></td><td style="text-align:left;">右键 <code>Disassemble</code> / <code>Create Function</code></td></tr><tr data-src-line="72" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><td style="text-align:left;">保存</td><td style="text-align:left;">数据库 <code>.i64</code></td><td style="text-align:left;">项目 + 分析结果</td></tr></tbody></table><h2 id="scripting" tabindex="-1" data-src-line="74" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">6. 脚本化：Ghidra 的独特优势 <a class="header-anchor" href="#scripting" aria-label="Permalink to &quot;6. 脚本化：Ghidra 的独特优势 {#scripting}&quot;">​</a></h2><p data-src-line="76" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">Ghidra 相对 IDA 免费版的一大优势是<strong>内置脚本引擎</strong>，支持 Java 和 Python（Jython），能批量、自动化地分析。入口是 <code>Window → Script Manager</code>，里面预置了大量官方脚本，也能新建自己的脚本。</p><p data-src-line="78" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">一个入门级的 Python 脚本——遍历当前程序所有函数，打印名字和地址：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在 Ghidra Script Manager 中新建 Python 脚本运行</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">listing </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> currentProgram.getListing()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> currentProgram.getFunctionManager()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> func </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fm.getFunctions(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">):</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%X\\t%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (func.getEntryPoint().getOffset(), func.getName()))</span></span></code></pre></div><p data-src-line="88" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">运行后，控制台会按地址升序打印所有函数。这个脚本本身不复杂，但它展示了脚本化的威力：<strong>同样的「遍历 + 处理」模式，稍加扩展就能做「找出所有调用 <code>WriteFile</code> 的函数」「列出所有含某个字符串的函数」这类批量任务</strong>，这是手动点按钮做不到或很慢的。</p><p data-src-line="90" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">脚本化适合当你需要重复、批量处理时再深入；日常单文件分析，手动操作足够。</p><h2 id="_7-失败与回退" tabindex="-1" data-src-line="92" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">7. 失败与回退 <a class="header-anchor" href="#_7-失败与回退" aria-label="Permalink to &quot;7. 失败与回退&quot;">​</a></h2><ul data-src-line="94" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><li data-src-line="94" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>启动报 Java 错误</strong>：JDK 版本不满足，按官方要求装对应版本并重新指定 JDK 路径。</li><li data-src-line="95" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>Auto Analyze 没跑或结果不全</strong>：<code>Analysis → Auto Analyze</code> 重新运行。</li><li data-src-line="96" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><strong>误删/误改分析结果想重来</strong>：Ghidra 的改动即时生效但可撤销（<code>Edit → Undo</code>）；彻底重来可重新导入文件。</li></ul><hr><blockquote data-src-line="100" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md"><p data-src-line="100" data-src-file="reverse-engineering/05-static-analysis/chapter-05-ghidra.md">本章用 Ghidra 完成了和 IDA 相同的静态分析，并引入了脚本化。Ghidra 与 IDA 的分析概念一一对应，区别只在命名和快捷键。下一章转到另一个维度——<a href="./../06-dynamic-debugging/chapter-01-debugging-basics.html">动态调试基础</a>，让程序跑起来观察它。</p></blockquote>`,34)])])}const y=a(r,[["render",n]]);export{p as __pageData,y as default};
